query SearchProducts($query: String!, $channel: String!, $attributes: [AttributeInput], $pageSize: Int, $sortBy: ProductOrder, $after: String) {
  products(
    channel: $channel
    filter: {search: $query, attributes: $attributes}
    first: $pageSize
    sortBy: $sortBy
    after: $after
  ) {
    totalCount
    edges {
      node {
        ...ProductPricingField
        id
        name
        slug
        thumbnail {
          url
          alt
        }
        thumbnail2x: thumbnail(size: 510) {
          url
        }
        category {
          id
          name
        }
      }
    }
    pageInfo {
      endCursor
      hasNextPage
    }
  }
  attributes(filter: {filterableInStorefront: true}, first: 100) {
    edges {
      node {
        ...Attribute
      }
    }
  }
}

fragment ProductPricingField on Product {
  pricing {
    onSale
    priceRangeUndiscounted {
      start {
        ...TaxedPrice
      }
      stop {
        ...TaxedPrice
      }
    }
    priceRange {
      start {
        ...TaxedPrice
      }
      stop {
        ...TaxedPrice
      }
    }
  }
}

fragment TaxedPrice on TaxedMoney {
  gross {
    ...Price
  }
  net {
    ...Price
  }
}

fragment Price on Money {
  amount
  currency
}

fragment Attribute on Attribute {
  id
  name
  slug
  choices(first: 100) {
    edges {
      node {
        id
        name
        slug
      }
    }
  }
}
